const chatwootToken = 'nuwRKpG2bBAQBpRFznfvrMpT';
const chatwootBase = 'https://project1-chatwoot.efebpb.easypanel.host/api/v1/accounts/1';

function detectLanguage(text, history = []) {
  if (!text) text = '';
  const clean = text.toLowerCase();

  const spWords = new Set(['hola','buenos','buenas','dias','tardes','noches','gracias','quiero','prueba','planes','precio','precios','cuanto','como','donde','amigo','por','favor','ayuda','cuenta','dispositivo','dispositivos','informacion','servicio','saludos','pago','tarjeta','movil','bolivares','mes','meses','ano','listo','que','cual','cuando','tengo','tienen','estoy','puedo','el','la','los','las','un','una','unos','unas','de','del','en','con','para','me','te','se','nos','gusto','mucho','excelente','bueno','bien']);
  const enWords = new Set(['hello','hi','hey','good','morning','afternoon','evening','thanks','thank','you','want','trial','plans','price','prices','how','much','where','please','help','account','device','devices','information','service','greetings','payment','card','month','months','year','ready','what','which','when','have','there','is','are','can','could','the','was','were','amazing','great','sports','channels','awesome','liked','loved','it','this','that','for','with','and','but','or','i','my','we','our']);

  const words = clean.replace(/[^a-záéíóúñ\s]/gi, ' ').split(/\s+/).filter(Boolean);
  let spCount = 0;
  let enCount = 0;
  for (const w of words) {
    if (spWords.has(w)) spCount++;
    if (enWords.has(w)) enCount++;
  }
  if (/[áéíóúñ¿¡]/.test(clean)) spCount += 2;

  if (spCount > enCount) return 'es';
  if (enCount > spCount) return 'en';

  for (let i = history.length - 1; i >= 0; i--) {
    const pClean = (history[i] || '').toLowerCase();
    const pWords = pClean.replace(/[^a-záéíóúñ\s]/gi, ' ').split(/\s+/).filter(Boolean);
    let pSp = 0, pEn = 0;
    for (const w of pWords) {
      if (spWords.has(w)) pSp++;
      if (enWords.has(w)) pEn++;
    }
    if (/[áéíóúñ¿¡]/.test(pClean)) pSp += 2;
    if (pSp > pEn) return 'es';
    if (pEn > pSp) return 'en';
  }

  return 'es';
}

const results = [];
const now = Date.now();

// 1. Fetch conversations with stage-fase-de-pruebas
let stageFasePruebasConvs = [];
try {
  const respFase = await this.helpers.httpRequest({
    method: 'GET',
    url: `${chatwootBase}/conversations?labels[]=stage-fase-de-pruebas`,
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  stageFasePruebasConvs = respFase.data?.payload || [];
} catch (e) {}

// 2. Fetch conversations with stage-que-te-parecio
let stageQueTeParecioConvs = [];
try {
  const respQue = await this.helpers.httpRequest({
    method: 'GET',
    url: `${chatwootBase}/conversations?labels[]=stage-que-te-parecio`,
    headers: { 'api_access_token': chatwootToken },
    json: true
  });
  stageQueTeParecioConvs = respQue.data?.payload || [];
} catch (e) {}

// Combine and deduplicate
const convMap = new Map();
for (const c of [...stageFasePruebasConvs, ...stageQueTeParecioConvs]) {
  if (c && c.id) convMap.set(c.id, c);
}

for (const [convId, conv] of convMap.entries()) {
  const currentLabels = Array.isArray(conv.labels) ? conv.labels : [];
  const customAttrs = conv.custom_attributes || {};
  const inboxId = Number(conv.inbox_id || 0);

  // Safety checks: skip human, terminal stages, resolved conversations, or TotalTv USA inboxes
  if (currentLabels.includes('human') || currentLabels.includes('stage-leads-ganados') || currentLabels.includes('stage-leads-perdidos') || conv.status === 'resolved') {
    continue;
  }
  if (inboxId === 1 || inboxId === 4 || inboxId === 6 || inboxId === 14 || inboxId === 17 || currentLabels.includes('funnel-totaltv-usa') || currentLabels.includes('totaltvusa')) {
    continue;
  }

  // PREVENT REPEAT: if already followed up, skip immediately!
  if (customAttrs.stage_que_te_parecio_followup_at) {
    continue;
  }

  let msgs = [];
  try {
    const msgResp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${chatwootBase}/conversations/${convId}/messages`,
      headers: { 'api_access_token': chatwootToken },
      json: true
    });
    msgs = msgResp.payload || [];
  } catch (e) {
    continue;
  }

  const customerMsgs = msgs.filter(m => (m.message_type === 0 || m.message_type === 'incoming') && m.private !== true);

  let lastCustomerTimeMs = 0;
  let lastCustomerContent = '';
  const customerHistory = [];

  if (customerMsgs.length > 0) {
    const lastMsg = customerMsgs[customerMsgs.length - 1];
    lastCustomerTimeMs = (lastMsg.created_at || lastMsg.created_at_epoch) * 1000;
    lastCustomerContent = lastMsg.content || '';
    for (const m of customerMsgs) {
      if (m.content) customerHistory.push(m.content);
    }
  } else {
    lastCustomerTimeMs = (conv.created_at || conv.last_activity_at) * 1000;
  }

  const elapsedHours = (now - lastCustomerTimeMs) / (1000 * 3600);

  if (elapsedHours >= 20) {
    // Transition label: clean all stage labels and set stage-que-te-parecio
    const updatedLabels = currentLabels.filter(l => !l.startsWith('stage-'));
    updatedLabels.push('stage-que-te-parecio');

    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/labels`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: { labels: updatedLabels },
        json: true
      });
    } catch (e) {}

    const lang = detectLanguage(lastCustomerContent, customerHistory);
    let followUpText = '';
    if (lang === 'en') {
      followUpText = 'Hello! 👋 We hope you enjoyed the trial we provided. How did you like the service? Would you be interested in subscribing to one of our plans? 😊';
    } else {
      followUpText = '¡Hola! 👋 Esperamos que hayas disfrutado la prueba que te dimos. ¿Qué te ha parecido el servicio? ¿Te interesa suscribirte a alguno de nuestros planes? 😊';
    }

    // Format for Meta channels (WhatsApp 16, Instagram 13, TikTok 15)
    if (inboxId === 16 || inboxId === 13 || inboxId === 15) {
      followUpText = followUpText.replace(/\*\*(.*?)\*\*/g, '*$1*');
      followUpText = followUpText.replace(/\[(.*?)\]\((.*?)\)/g, '$1: $2');
    }

    // Send outgoing message
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/messages`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: {
          content: followUpText,
          message_type: 'outgoing',
          private: false
        },
        json: true
      });
    } catch (e) {}

    // Mark custom attribute MERGED with existing attributes
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: `${chatwootBase}/conversations/${convId}/custom_attributes`,
        headers: {
          'api_access_token': chatwootToken,
          'Content-Type': 'application/json'
        },
        body: {
          custom_attributes: {
            ...customAttrs,
            stage_que_te_parecio_followup_at: new Date().toISOString()
          }
        },
        json: true
      });
    } catch (e) {}

    results.push({
      convId,
      action: 'transitioned_and_sent',
      elapsedHours: Math.round(elapsedHours * 10) / 10,
      language: lang
    });
  } else {
    results.push({
      convId,
      action: 'waiting',
      elapsedHours: Math.round(elapsedHours * 10) / 10,
      neededHours: 20
    });
  }
}

return [{
  json: {
    timestamp: new Date().toISOString(),
    processed_count: results.length,
    results
  }
}];
